using DownhillRoguelite.Core;
using Godot;

namespace DownhillRoguelite.Audio;

/// <summary>
/// Ambient music: a day loop and a night loop played together and crossfaded by the clock's
/// daylight, ducked while the narrator speaks. Plays on the "Music" bus and keeps playing while
/// paused. The loops are generated by audio/tools/generate_ambient.py.
/// </summary>
public partial class MusicPlayer : Node
{
    [Export] public AudioStream? DayTrack { get; set; }
    [Export] public AudioStream? NightTrack { get; set; }
    [Export] public StringName Bus { get; set; } = "Music";
    /// <summary>Volume of a track at full mix, in dB.</summary>
    [Export] public float VolumeDb { get; set; } = -3.0f;
    /// <summary>Extra drop while the narrator speaks, in dB.</summary>
    [Export] public float DuckDb { get; set; } = -9.0f;
    /// <summary>Drop while the summit car's radio plays one of the player's songs, in dB.</summary>
    [Export] public float RadioDuckDb { get; set; } = -40.0f;
    /// <summary>How fast volumes follow their targets (per second).</summary>
    [Export] public float FadeSpeed { get; set; } = 1.5f;

    private AudioStreamPlayer? _day;
    private AudioStreamPlayer? _night;
    private WorldClock? _clock;
    private float _duck;
    private float _radioDuck;

    public override void _Ready()
    {
        ProcessMode = ProcessModeEnum.Always;
        _clock = GetNodeOrNull<WorldClock>("/root/WorldClock");
        _day = AddTrack(DayTrack);
        _night = AddTrack(NightTrack);
    }

    private AudioStreamPlayer AddTrack(AudioStream? stream)
    {
        if (stream is AudioStreamWav wav)
        {
            wav.LoopMode = AudioStreamWav.LoopModeEnum.Forward;
            wav.LoopBegin = 0;
            wav.LoopEnd = Mathf.FloorToInt((float)wav.GetLength() * wav.MixRate);
        }
        AudioStreamPlayer player = new() { Stream = stream, Bus = Bus, VolumeDb = -80.0f };
        AddChild(player);
        // Headless runs (tests, smoke) have no real audio output and never release playing streams.
        if (stream != null && DisplayServer.GetName() != "headless")
        {
            player.Play();
        }
        return player;
    }

    public override void _ExitTree()
    {
        foreach (AudioStreamPlayer? player in new[] { _day, _night })
        {
            if (player != null)
            {
                player.Stop();
                player.Stream = null;
            }
        }
        DayTrack = null;
        NightTrack = null;
    }

    public override void _Process(double delta)
    {
        float daylight = 1.0f;
        if (_clock != null)
        {
            daylight = _clock.Daylight;
        }
        float duckTarget = 0.0f;
        if (GameEvents.IsNarrating || GameEvents.IsSpeaking)
        {
            duckTarget = 1.0f;
        }
        _duck = Mathf.MoveToward(_duck, duckTarget, FadeSpeed * (float)delta);
        float radioTarget = 0.0f;
        if (GameEvents.IsRadioPlaying)
        {
            radioTarget = 1.0f;
        }
        _radioDuck = Mathf.MoveToward(_radioDuck, radioTarget, FadeSpeed * (float)delta);
        Fade(_day, daylight, delta);
        Fade(_night, 1.0f - daylight, delta);
    }

    private void Fade(AudioStreamPlayer? player, float mix, double delta)
    {
        if (player == null)
        {
            return;
        }
        float linear = Mathf.Clamp(mix, 0.0001f, 1.0f);
        float target = VolumeDb + Mathf.LinearToDb(linear) + DuckDb * _duck + RadioDuckDb * _radioDuck;
        player.VolumeDb = Mathf.MoveToward(player.VolumeDb, target, 30.0f * FadeSpeed * (float)delta);
    }
}
